import jsonschema

class MetaSchemaRegistry:
    def __init__(self):
        # Initialize an empty dictionary to store meta-schemas and vocabularies
        self.registry = {}

    def register_schema(self, name, schema):
        # Register a new meta-schema in the registry
        self.registry[name] = schema

    def get_schema(self, name):
        # Retrieve a registered meta-schema by its name
        return self.registry.get(name)

    def list_schemas(self):
        # List all registered meta-schemas in the registry
        return list(self.registry.keys())

    def validate_data(self, data, schema_name):
        # Validate a piece of data against a specific schema
        try:
            jsonschema.validate(instance=data, schema=self.get_schema(schema_name))
            return True
        except jsonschema.exceptions.ValidationError as e:
            print(f"Validation error: {e}")
            return False

# Example usage
registry = MetaSchemaRegistry()
registry.register_schema('example', {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"}
    },
    "required": ["name", "age"]
})

print("Registered schemas:", registry.list_schemas())
data_to_validate = {'name': 'John Doe', 'age': 30}
is_valid = registry.validate_data(data_to_validate, 'example')
print("Data validation result:", is_valid)
```

