import websocket
import threading

class WebSocketProxy:
    def __init__(self):
        self.clients = []
        self.proxy_server = websocket.WebSocketServer(8765, handler_class=WebSocketHandler)

    def start_proxy(self):
        print("Starting WebSocket Proxy...")
        self.proxy_server.serve_forever()

class WebSocketHandler(websocket.WebSocketHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.client_name = None

    def on_open(self):
        self.client_name = f"Client {len(self.clients) + 1}"
        self.clients.append(self)
        print(f"{self.client_name} connected")

    def on_message(self, message):
        if self.client_name:
            print(f"{self.client_name} received: {message}")
            for client in self.clients:
                if client != self:
                    client.send(f"{self.client_name}: {message}")

    def on_close(self):
        self.clients.remove(self)
        print(f"{self.client_name} disconnected")

if __name__ == "__main__":
    proxy = WebSocketProxy()
    proxy.start_proxy()
```

This code snippet defines a `WebSocketProxy` class that sets up a WebSocket server using the `websocket` library. It handles incoming connections from clients, receives messages from clients, and broadcasts them to all other connected clients. Each client has a unique name assigned by the server upon connection. The `WebSocketHandler` class extends `websocket.WebSocketHandler` and overrides methods to manage client connections, messages, and disconnections. When the script runs, it starts the WebSocket proxy on port 8765 and listens for incoming connections.

