import json

# Define the JSONPath grammar rules
JSONPATH_GRAMMAR = """
    expression: element | path_expression | array_expression
    element: identifier | number
    path_expression: path_elements [index]
    array_expression: array_elements [index]
    path_elements: path_element*
    path_element: identifier | index
    index: '[' number ']'
    number: digit+
    identifier: letter+ digit*
    digit: 0-9
    letter: A-Z | a-z
"""

# Tokenize the JSONPath expression
def tokenize(expression):
    tokens = []
    current_token = ""
    in_number = False
    in_string = False
    for char in expression:
        if char == '"':
            if in_string:
                tokens.append((current_token, 'STRING'))
                current_token = ""
                in_string = False
            else:
                in_string = True
        elif char.isdigit():
            if in_number:
                current_token += char
            else:
                current_token = char
                in_number = True
        elif char.isalpha():
            if in_number:
                tokens.append((current_token, 'NUMBER'))
                current_token = ""
                in_number = False
            else:
                current_token += char
        elif char == '[':
            tokens.append((current_token, 'BRACKET_OPEN'))
            current_token = ""
        elif char == ']':
            tokens.append((current_token, 'BRACKET_CLOSE'))
            current_token = ""
        elif char == ',':
            tokens.append((current_token, 'COMMA'))
            current_token = ""
        elif char == ' ':
            continue
        else:
            raise ValueError(f"Invalid character '{char}' in JSONPath expression")
    if current_token:
        tokens.append((current_token, 'END'))
    return tokens

# Parse the JSONPath expression into an AST
class Node:
    def __init__(self, type, value=None):
        self.type = type
        self.value = value

def parse(tokens):
    ast = []
    i = 0
    while i < len(tokens):
        token_type, token_value = tokens[i]
        if token_type == 'IDENTIFIER':
            node = Node('IDENTIFIER', token_value)
            ast.append(node)
            i += 1
        elif token_type == 'NUMBER':
            node = Node('NUMBER', int(token_value))
            ast.append(node)
            i += 1
        elif token_type == 'BRACKET_OPEN':
            i += 1
            node = Node('ARRAY_ELEMENT')
            ast.append(node)
            while i < len(tokens) and tokens[i][0] != 'BRACKET_CLOSE':
                child_node = parse(tokens)
                node.children.append(child_node)
                i += 1
            if i < len(tokens) and tokens[i][0] == 'BRACKET_CLOSE':
                i += 1
        elif token_type == 'INDEX':
            i += 1
            node = Node('INDEX')
            node.index = int(tokens[i][1])
            i += 1
        elif token_type == 'STRING':
            node = Node('STRING', token_value)
            ast.append(node)
            i += 1
        elif token_type == 'COMMA':
            i += 1
        elif token_type == 'END':
            break
    return ast

# Evaluate the parsed JSONPath expression
def evaluate(ast, data):
    if ast.type == 'IDENTIFIER':
        return data.get(ast.value)
    elif ast.type == 'NUMBER':
        return ast.value
    elif ast.type == 'BRACKET_ELEMENT':
        result = evaluate(ast.children[0], data)
        if not isinstance(result, list):
            raise ValueError("Array expected")
        index = ast.children[1].value
        if index < len(result):
            return result[index]
        else:
            raise IndexError("Index out of range")
    elif ast.type == 'INDEX':
        return data[ast.index]
    else:
        raise ValueError("Unsupported node type")

# Example usage
json_data = {"name": "John", "age": 30, "children": [{"name": "Alice"}, {"name": "Bob"}]}
json_path = "$.children[1].name"
tokens = tokenize(json_path)
ast = parse(tokens)
result = evaluate(ast, json_data)
print(result)  # Output: Bob
