class BinaryDataManager:
    def __init__(self):
        # Initialize an empty dictionary to store binary data
        self.data_dict = {}

    def encode_data(self, key, value):
        # Encode the given value into bytes
        encoded_value = value.encode('utf-8')
        # Store the encoded value in the dictionary using the provided key
        self.data_dict[key] = encoded_value

    def decode_data(self, key):
        # Retrieve the encoded value from the dictionary using the provided key
        if key in self.data_dict:
            # Decode the bytes back into a string
            decoded_value = self.data_dict[key].decode('utf-8')
            return decoded_value
        else:
            return None  # Return None if the key does not exist

    def store_data(self, key, value):
        # Call encode_data to encode the value before storing it
        self.encode_data(key, value)

    def retrieve_data(self, key):
        # Call decode_data to retrieve the value after decoding
        return self.decode_data(key)

    def iterate_over_data(self):
        # Iterate over the dictionary keys and print each one along with its corresponding value
        for key in self.data_dict:
            value = self.retrieve_data(key)
            if value is not None:
                print(f"Key: {key}, Value: {value}")

# Example usage:
manager = BinaryDataManager()
manager.store_data("name", "Alice")
manager.store_data("age", "30")
manager.iterate_over_data()  # Output: Key: name, Value: Alice Key: age, Value: 30
