import pyparsing as pp

# Define the grammar for C-family language
def c_family_grammar():
    # Tokens for basic syntax elements
    keyword = pp.Word(pp.alphas)
    identifier = pp.Word(pp.alphanums + '_')
    number = pp.Word(pp.nums)
    operator = pp.oneOf('+-*/<>==!=')

    # Basic structure: statement block
    statement_block = pp.Group(pp.OneOrMore(statement))

    # Statements can be assignments, declarations, or compound statements
    assignment = (identifier + operator + expression) | declaration | compound_statement
    declaration = (keyword + identifier) + pp.Optional(type_specification)
    compound_statement = '{' + statement_block + '}'

    # Expressions can be numbers, identifiers, or arithmetic operations
    expression = (number | identifier) | arithmetic_expression
    arithmetic_expression = (arithmetic_expression + operator + arithmetic_expression)

    # Type specifications are optional in C-family languages
    type_specification = pp.Empty()  # Placeholder for future types

    # Combining all parts into a single parser
    return pp.Forward() >> (statement_block | assignment | declaration | compound_statement)

# Function to generate AST from parsed tokens
def generate_ast(tokens):
    ast = {}
    current_node = ast
    for token in tokens:
        if isinstance(token, pp.Keyword):
            current_node[token.value] = {}
            current_node = current_node[token.value]
        elif isinstance(token, pp.Identifier):
            current_node[token.value] = None
            current_node = current_node[token.value]
        elif isinstance(token, pp.Number):
            current_node[token.value] = None
            current_node = current_node[token.value]
        elif isinstance(token, pp.Operator):
            current_node[token.value] = {}
            current_node = current_node[token.value]
        elif isinstance(token, pp.String):
            current_node[token.value] = None
            current_node = current_node[token.value]
        else:
            raise ValueError("Unexpected token")
    return ast

# Example usage
c_code = """
int main() {
    int x = 10;
    if (x > 5) {
        printf("x is greater than 5");
    } else {
        printf("x is not greater than 5");
    }
    return 0;
}
"""
tokens = c_family_grammar().parseString(c_code)
ast = generate_ast(tokens)
print(ast)
```

