class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, current_node, value):
        if value < current_node.value:
            if not current_node.left:
                current_node.left = TreeNode(value)
            else:
                self._insert_recursive(current_node.left, value)
        elif value > current_node.value:
            if not current_node.right:
                current_node.right = TreeNode(value)
            else:
                self._insert_recursive(current_node.right, value)
        else:
            print("Duplicate value: ", value)

    def delete(self, value):
        if not self.root:
            return "Tree is empty"
        else:
            self._delete_recursive(self.root, value)

    def _delete_recursive(self, current_node, value):
        if not current_node:
            return "Value not found in the tree"

        # If the value is smaller than the current node's value,
        # it lies in the left subtree
        if value < current_node.value:
            current_node.left = self._delete_recursive(current_node.left, value)
        # If the value is greater than the current node's value,
        # it lies in the right subtree
        elif value > current_node.value:
            current_node.right = self._delete_recursive(current_node.right, value)
        # If the value is equal to the current node's value,
        # we have found the node to be deleted
        else:
            # Case 1: No children or one child
            if not current_node.left:
                temp = current_node.right
                del current_node
                return temp
            elif not current_node.right:
                temp = current_node.left
                del current_node
                return temp

            # Case 2: Two children
            temp = self._find_min_value_node(current_node.right)
            current_node.value = temp.value
            current_node.right = self._delete_recursive(current_node.right, temp.value)

        return current_node

    def find(self, value):
        return self._find_recursive(self.root, value)

    def _find_recursive(self, current_node, value):
        if not current_node:
            return False

        if value == current_node.value:
            return True

        if value < current_node.value:
            return self._find_recursive(current_node.left, value)
        else:
            return self._find_recursive(current_node.right, value)

# Example usage:
bst = BinarySearchTree()
bst.insert(50)
bst.insert(30)
bst.insert(70)
bst.insert(20)
bst.insert(40)
bst.insert(60)
bst.insert(80)

print(bst.find(40))  # Output: True
print(bst.find(90))  # Output: False

bst.delete(40)
print(bst.find(40))  # Output: False
```

**Explanation**:
This solution provides a complete implementation of a binary search tree (BST) using Python classes. The `TreeNode` class represents individual nodes in the BST, containing a value and pointers to its left and right children.

The `BinarySearchTree` class manages the overall tree structure and provides methods for inserting, deleting, and searching values within the tree. The insertion method recursively searches for the correct position to insert the new value. The deletion method uses a recursive approach to locate and remove the node, handling cases where the node has no children, one child, or two children.

The search method also employs recursion to traverse the tree until it finds the desired value or determines that it does not exist in the tree. This approach ensures that the BST remains balanced after each operation, which is crucial for performance in large datasets.

