import json

class JSONSchema:
    def __init__(self, schema):
        # Initialize the schema dictionary
        self.schema = schema

    def get_attribute(self, path):
        # Helper method to traverse the schema
        current_level = self.schema
        for key in path.split('.'):
            if isinstance(current_level, dict) and key in current_level:
                current_level = current_level[key]
            else:
                return None
        return current_level

    def validate_data(self, data):
        # Validate the data against the schema
        errors = []
        for key, value in data.items():
            attribute = self.get_attribute(key)
            if attribute is not None:
                if not isinstance(value, attribute['type']):
                    errors.append(f"Error: Expected {attribute['type']}, got {type(value).__name__} for key '{key}'")
            elif 'required' in self.schema and key not in self.schema['required']:
                errors.append(f"Error: Key '{key}' is not defined as required in the schema.")
        return errors

    def format_data(self, data):
        # Format the data according to the schema
        formatted_data = {}
        for key, value in data.items():
            attribute = self.get_attribute(key)
            if attribute is not None:
                if attribute['format'] == 'date':
                    formatted_data[key] = value.strftime('%Y-%m-%d')
                elif attribute['format'] == 'time':
                    formatted_data[key] = value.strftime('%H:%M:%S')
                elif attribute['format'] == 'email':
                    formatted_data[key] = value.lower()  # Convert email to lowercase
                else:
                    formatted_data[key] = value
        return formatted_data

