            print(f"Notebook does not exist: {notebook_path}")

# Example usage
cache = NotebookCache()
cache.add_notebook("path/to/notebook1.ipynb")
cache.add_notebook("path/to/notebook2.ipynb")
print(cache.get_notebooks())  # Output: ['path/to/notebook1.ipynb', 'path/to/notebook2.ipynb']
cache.remove_notebook("path/to/notebook1.ipynb")
print(cache.get_notebooks())  # Output: ['path/to/notebook2.ipynb']
```

